from ...lteuegroup import LteUeGroup
from ute_common_abstract_core.network_elem_identification import MsgSourceIdentification, UeIdentification
from ...ue.demo import CommandSender
from ...exceptions import UeProcedureError


class DemoUeGroup(LteUeGroup):
    """DemoUeGroup class provides simple ue-group implementation for usage demonstration purpose."""
    def __init__(self, ues):
        """
        Construct Demo UE-group

        :param ues: UEs carried by group
        """
        super().__init__(ues=ues)
        self._console = CommandSender()
        self._activate_msg_source()
        self._ues_status = dict.fromkeys(self._ids_of_group_ues(), 'detached')  # key is ue id, value is: attached, detached

    def _activate_msg_source(self):
        MsgSourceIdentification(identifiers=[('demo', self._ids_of_group_ues())],
                                network_elem_type='UE_GROUP',
                                specific_for_tool='demo')
        for ue_id in self._ids_of_group_ues():
            UeIdentification(identifiers=[('demo', ue_id)], network_elem_type='UE',
                             specific_for_tool='demo')

    def _ids_of_group_ues(self):
        group_ue_ids = [ue.configuration['CONSTRUCTOR_PARAMETERS']['configuration']['id'] for ue in self.ues]
        return group_ue_ids

    def shutdown(self):
        """UE group specific cleanups"""
        for ue_id in self._ids_of_group_ues():
            cmd = f"disconnect ue id={ue_id}"
            cmd_succeeded = self._console.send(command=cmd)
            self.logger.info("{} sending command: {}".format('SUCCESS' if cmd_succeeded else 'FAILURE', cmd))

    def attach(self, success_ratio=None, failure_ratio=None, timeout=-1):
        """Perform attach on each UE of group"""
        failed_attaches = 0
        ids_to_attach = self._ids_with_status(status="detached")
        for ue_id in ids_to_attach:
            cmd = f"attach ue id={ue_id}"
            cmd_succeeded = self._console.send(command=cmd)
            self.logger.info("{} sending command: {}".format('SUCCESS' if cmd_succeeded else 'FAILURE', cmd))
            if not cmd_succeeded:
                failed_attaches += 1
            self._ues_status[ue_id] = "attached" if cmd_succeeded else "detached"
        if failed_attaches:
            err_msg = f"{self} attach failed: {failed_attaches} of {len(ids_to_attach)} UEs failed to attach"
            raise UeProcedureError(err_msg)

    def detach(self, timeout=-1):
        """Perform detach on each UE of group"""
        failed_detaches = 0
        ids_to_detach = self._ids_with_status(status="attached")
        for ue_id in ids_to_detach:
            cmd = f"detach ue id={ue_id}"
            cmd_succeeded = self._console.send(command=cmd)
            self.logger.info("{} sending command: {}".format('SUCCESS' if cmd_succeeded else 'FAILURE', cmd))
            if not cmd_succeeded:
                failed_detaches += 1
            self._ues_status[ue_id] = "detached" if cmd_succeeded else "attached"
        if failed_detaches:
            err_msg = f"{self} detach failed: {failed_detaches} of {len(ids_to_detach)} UEs failed to detach"
            raise UeProcedureError(err_msg)

    def _ids_with_status(self, status):
        selected_ids = [ue_id for ue_id in self._ids_of_group_ues() if self._ues_status[ue_id] == status]
        return selected_ids
